/**
 * One Admin-uploaded walkthrough video, replacing the "coming soon" placeholder
 * on the User Guide's Getting Started tab for EVERY account. Writes gated on
 * manageAccounts, reads open to any signed-in account. Own "mustergo/guide"
 * Cloudinary folder (lib/cloudinary.js); same memory-storage multer pattern as
 * announcement images, but resource_type "video" and a far larger size cap.
 */
import { Router } from "express";
import multer from "multer";
import { wrap } from "../lib/wrap.js";
import { requireAuth, requirePermission } from "../lib/auth.js";
import { actorOf } from "../lib/actor.js";
import { getGuideVideo, setGuideVideo, clearGuideVideo } from "../db/guideVideo.js";
import { isConfigured as videoStorageConfigured, uploadVideo, destroyVideo, GUIDE_VIDEO_FOLDER } from "../lib/cloudinary.js";

const router = Router();

const MAX_GUIDE_VIDEO_BYTES = 100 * 1024 * 1024; // 100MB — a few minutes of screen recording

const guideVideoUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: MAX_GUIDE_VIDEO_BYTES },
  fileFilter: (_req, file, cb) => {
    if (!file.mimetype.startsWith("video/")) return cb(new Error("UNSUPPORTED_TYPE"));
    cb(null, true);
  },
});

router.get("/api/guide-video", requireAuth(), wrap(async (_req, res) => {
  res.json({ video: await getGuideVideo() });
}));

router.post("/api/guide-video", requirePermission("manageAccounts"), (req, res, next) => {
  guideVideoUpload.single("video")(req, res, (err) => {
    if (err) {
      const code = err.message === "UNSUPPORTED_TYPE" ? "UNSUPPORTED_TYPE" : "UPLOAD_FAILED";
      const message = code === "UNSUPPORTED_TYPE"
        ? "Please upload a video file."
        : `Upload too large (${MAX_GUIDE_VIDEO_BYTES / 1024 / 1024}MB max) or failed.`;
      return res.status(400).json({ error: code, message });
    }
    next();
  });
}, wrap(async (req, res) => {
  if (!req.file) return res.status(400).json({ error: "VIDEO_REQUIRED", message: "Please choose a video file." });
  if (!videoStorageConfigured()) {
    return res.status(503).json({ error: "VIDEO_STORAGE_NOT_CONFIGURED", message: "Video storage isn't set up on this server yet." });
  }

  const previous = await getGuideVideo();
  const uploaded = await uploadVideo(req.file.buffer, GUIDE_VIDEO_FOLDER);
  const video = await setGuideVideo({ url: uploaded.url, publicId: uploaded.publicId }, actorOf(req) || "Admin");
  if (previous?.publicId) await destroyVideo(previous.publicId);
  res.status(201).json({ video });
}));

router.delete("/api/guide-video", requirePermission("manageAccounts"), wrap(async (_req, res) => {
  const publicId = await clearGuideVideo();
  if (publicId) await destroyVideo(publicId);
  res.json({ ok: true });
}));

export default router;
